<?php

namespace Database\Factories;

use App\Enums\AssetCategory;
use App\Enums\AssetStatus;
use App\Enums\Currency;
use App\Models\Asset;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Asset>
 */
class AssetFactory extends Factory
{
    protected $model = Asset::class;

    public function definition(): array
    {
        $title = fake()->unique()->streetName().' Residence';

        return [
            'title' => $title,
            // slug + reference are auto-generated by the model when blank.
            'summary' => fake()->sentence(12),
            'category' => AssetCategory::Sale,
            'status' => AssetStatus::Published,
            'currency' => Currency::USD,
            'price' => fake()->numberBetween(100000, 900000),
            'price_period' => 'total',
            'beds' => (string) fake()->numberBetween(2, 5),
            'baths' => (string) fake()->numberBetween(2, 5),
            'location' => 'East Legon, Accra',
            'location_area' => 'East Legon',
            'area_key' => 'east-legon',
            'title_verified' => true,
            'published_at' => now(),
        ];
    }

    public function draft(): static
    {
        return $this->state(['status' => AssetStatus::Draft, 'published_at' => null]);
    }

    public function sold(): static
    {
        return $this->state(['status' => AssetStatus::Sold]);
    }

    public function land(): static
    {
        return $this->state(['category' => AssetCategory::Land, 'beds' => null, 'baths' => null, 'plot_size' => '2 plots · 0.5 acres']);
    }

    public function exclusive(): static
    {
        return $this->state(['is_exclusive' => true]);
    }

    public function featured(): static
    {
        return $this->state(['is_featured' => true]);
    }
}
